sapEthCfmTunnelFaultNotification = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 4, 3, 120, 1, 2), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(0, 1, 2))).clone(namedValues=NamedValues(("notApplicable", 0), ("accept", 1), ("ignore", 2))).clone('accept')).setMaxAccess("readcreate")
