sapDcpDynamicConform = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 4, 3, 0, 46)).setObjects(("TIMETRA-SAP-MIB", "sapDcpFpDynExcdCountHi"), ("TIMETRA-SAP-MIB", "sapDcpFpDynExcdCountLo"), ("TIMETRA-SAP-MIB", "sapDCpuProtPolicy"), ("TIMETRA-SAP-MIB", "sapDcpTimeEventOccured"))
if mibBuilder.loadTexts: sapDcpDynamicConform.setStatus('current')
if mibBuilder.loadTexts: sapDcpDynamicConform.setDescription("[CAUSE] The sapDcpDynamicConform notification is generated when the\n         protocol for a particular SAP has been detected as conformant for a\n         period of the configured detection-time after having been previously\n         detected as exceeding and completed any hold-down period. This\n         notification is generated when\n         TIMETRA-SECURITY-MIB.mib::tmnxDCpuProtStaticPlcrLogEvent is configured\n         to 'enable' or 'verbose'.\n\n         [EFFECT] The affected SAP is now in conformance with the parameters\n         configured for the associated distributed CPU protection policy.\n\n         [RECOVERY] There is no recovery required for this notification.")
sapDcpLocMonExcd = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 4, 3, 0, 47)).setObjects(("TIMETRA-SAP-MIB", "sapDcpFpLocMonExcdCountHi"), ("TIMETRA-SAP-MIB", "sapDcpFpLocMonExcdCountLo"), ("TIMETRA-SAP-MIB", "sapDCpuProtPolicy"), ("TIMETRA-SAP-MIB", "sapDcpTimeEventOccured"))
if mibBuilder.loadTexts: sapDcpLocMonExcd.setStatus('current')
if mibBuilder.loadTexts: sapDcpLocMonExcd.setDescription("[CAUSE] The sapDcpLocMonExcd notification is generated when the\n         local-monitoring-policer for a particular SAP has transitioned from a\n         conformant state to a non-conformant state and the system will attempt\n         to allocate dynamic enforcement policers. This notification is\n         generated when\n         TIMETRA-SECURITY-MIB.mib::tmnxDCpuProtLocMonPlcrLogEvent is configured\n         to 'verbose'.\n\n         [EFFECT] The affected SAP may be using more resources than expected\n         and cause the system to underperform. This notification may indicate a\n         Denial of Service attack or a misconfiguration in the network.\n\n         [RECOVERY] Appropriate configuration changes to the distributed CPU\n         protection policy or to the affected SAP may be required.")
sapDcpLocMonExcdDynResource = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 4, 3, 0, 48)).setObjects(("TIMETRA-SAP-MIB", "sapDcpFpLocMonExcdCountHi"), ("TIMETRA-SAP-MIB", "sapDcpFpLocMonExcdCountLo"), ("TIMETRA-SAP-MIB", "sapDCpuProtPolicy"), ("TIMETRA-SAP-MIB", "sapDcpTimeEventOccured"))
if mibBuilder.loadTexts: sapDcpLocMonExcdDynResource.setStatus('current')
if mibBuilder.loadTexts: sapDcpLocMonExcdDynResource.setDescription("[CAUSE] The sapDcpLocMonExcdDynResource notification is generated when\n         the local-monitoring-policer for a particular SAP has transitioned\n         from a conformant state to a non-conformant state and the system\n         cannot allocate all the dynamic enforcements policers associated with\n         the distributed CPU protection policy . This notification is generated\n         when TIMETRA-SECURITY-MIB.mib::tmnxDCpuProtLocMonPlcrLogEvent is\n         configured to 'enable' or 'verbose'.\n\n         [EFFECT] The affected SAP may be using more resources than expected\n         and cause the system to underperform. This notification may indicate a\n         Denial of Service attack or a misconfiguration in the network.\n\n         [RECOVERY] Appropriate configuration changes to the distributed CPU\n         protection policy or to the affected SAP or to the dynamic enforcement\n         policer pool(TIMETRA-CHASSIS-MIB.mib::tmnxFPDCpuProtDynEnfrcPlcrPool).")
sapDcpLocMonExcdAllDynAlloc = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 4, 3, 0, 49)).setObjects(("TIMETRA-SAP-MIB", "sapDcpFpLocMonExcdCountHi"), ("TIMETRA-SAP-MIB", "sapDcpFpLocMonExcdCountLo"), ("TIMETRA-SAP-MIB", "sapDCpuProtPolicy"), ("TIMETRA-SAP-MIB", "sapDcpTimeEventOccured"))
if mibBuilder.loadTexts: sapDcpLocMonExcdAllDynAlloc.setStatus('current')
if mibBuilder.loadTexts: sapDcpLocMonExcdAllDynAlloc.setDescription("[CAUSE] The sapDcpLocMonExcdAllDynAlloc notification is generated when\n         all dynamic enforcement policers associated with a non-conformant\n         local-monitoring-policer have been successfully allocated for a\n         particular SAP. This notification is generated when\n         TIMETRA-SECURITY-MIB.mib::tmnxDCpuProtLocMonPlcrLogEvent is configure\n         to 'verbose'.\n\n         [EFFECT] The affected SAP may be using more resources than expected\n         and cause the system to underperform.\n\n         [RECOVERY] Appropriate configuration changes to the distributed CPU\n         protection policy or to the affected SAP may be required.")
sapDcpLocMonExcdAllDynFreed = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 4, 3, 0, 50)).setObjects(("TIMETRA-SAP-MIB", "sapDcpFpLocMonState"), ("TIMETRA-SAP-MIB", "sapDCpuProtPolicy"), ("TIMETRA-SAP-MIB", "sapDcpTimeEventOccured"))
if mibBuilder.loadTexts: sapDcpLocMonExcdAllDynFreed.setStatus('current')
if mibBuilder.loadTexts: sapDcpLocMonExcdAllDynFreed.setDescription("[CAUSE] The sapDcpLocMonExcdAllDynFreed notification is generated for\n         a particular SAP when all the previously allocated dynamic enforcement\n         policers for a particular local-monitoring-policer on the associated\n         distributed CPU protection policy have been freed up and all the\n         protocols are once again being monitored by local-monitor. This\n         notification is generated when\n         TIMETRA-SECURITY-MIB.mib::tmnxDCpuProtLocMonPlcrLogEvent is configured\n         to 'verbose'.\n\n         [EFFECT] The affected SAP may be using more resources than expected\n         and cause the system to underperform.\n\n         [RECOVERY] There is no recovery required for this notification.")
sapDcpDynamicEnforceAlloc = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 4, 3, 0, 51)).setObjects(("TIMETRA-SAP-MIB", "sapDcpFpDynAllocated"), ("TIMETRA-SAP-MIB", "sapDCpuProtPolicy"), ("TIMETRA-SAP-MIB", "sapDcpTimeEventOccured"))
if mibBuilder.loadTexts: sapDcpDynamicEnforceAlloc.setStatus('current')
if mibBuilder.loadTexts: sapDcpDynamicEnforceAlloc.setDescription("[CAUSE] The sapDcpDynamicEnforceAlloc notification is generated when a\n         dynamic enforcement policer is allocated on a particular SAP. This\n         notification is generated when\n         TIMETRA-SECURITY-MIB.mib::tmnxDCpuProtProtocolDynLogEvent is\n         configured to 'verbose'.\n\n         [EFFECT] The affected SAP is not in conformance with the configured\n         parameters of the associated distributed CPU protection policy and may\n         be using more resources than expected and cause the system to\n         underperform.\n\n         [RECOVERY] Appropriate configuration changes to the distributed CPU\n         protection policy or to the affected SAP may be required.")
sapDcpDynamicEnforceFreed = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 4, 3, 0, 52)).setObjects(("TIMETRA-SAP-MIB", "sapDcpFpDynExcdCountHi"), ("TIMETRA-SAP-MIB", "sapDcpFpDynExcdCountLo"), ("TIMETRA-SAP-MIB", "sapDCpuProtPolicy"), ("TIMETRA-SAP-MIB", "sapDcpTimeEventOccured"))
if mibBuilder.loadTexts: sapDcpDynamicEnforceFreed.setStatus('current')
if mibBuilder.loadTexts: sapDcpDynamicEnforceFreed.setDescription("[CAUSE] The sapDcpDynamicEnforceFreed notification is generated when a\n         dynamic enforcement policer is freed on a particular SAP. This\n         notification is generated when\n         TIMETRA-SECURITY-MIB.mib::tmnxDCpuProtProtocolDynLogEvent is\n         configured to 'verbose'.\n\n         [EFFECT] The affected SAP is now in conformance with the configured\n         parameters of the associated distributed CPU protection policy.\n\n         [RECOVERY] There is no recovery required for this notification.")
sapTlsMacMoveExceedNonBlock = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 4, 3, 0, 53)).setObjects(("TIMETRA-SERV-MIB", "custId"), ("TIMETRA-SERV-MIB", "svcId"), ("TIMETRA-SERV-MIB", "svcVpnId"), ("TIMETRA-SAP-MIB", "sapPortId"), ("TIMETRA-SAP-MIB", "sapEncapValue"), ("TIMETRA-SERV-MIB", "svcTlsMacMoveMaxRate"), ("TIMETRA-SAP-MIB", "sapTlsNotifyMacAddr"))
if mibBuilder.loadTexts: sapTlsMacMoveExceedNonBlock.setStatus('current')
if mibBuilder.loadTexts: sapTlsMacMoveExceedNonBlock.setDescription("[CAUSE] The sapTlsMacMoveExceedNonBlock notification is generated when\n         the SAP exceeds the TLS svcTlsMacMoveMaxRate when sapTlsLimitMacMove\n         is set to 'nonBlocking'. In case of Provider Backbone Bridging (PBB),\n         if the MAC address that exceeds the rate is ISID-VPLS(iVpls) FDB and\n         sap binding that detects the move is in Backbone-VPLS(bVpls), the\n         notification will be generated with svcId, custId of I-VPLS and B-VPLS\n         sapId.\n\n         [EFFECT] This notification is informational only.\n\n         [RECOVERY] User can adjust the value of svcTlsMacMoveMaxRate to reduce\n         the frequency of this notification.")
sapEthLoopbackStarted = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 4, 3, 0, 54)).setObjects(("TIMETRA-SAP-MIB", "sapEthLoopbackMode"), ("TIMETRA-SAP-MIB", "sapEthLoopbackMacSwap"), ("TIMETRA-SAP-MIB", "sapEthLoopbackMacSwapAddr"), ("TIMETRA-SAP-MIB", "sapEthLoopbackMacSwapAddrAll"))
if mibBuilder.loadTexts: sapEthLoopbackStarted.setStatus('current')
if mibBuilder.loadTexts: sapEthLoopbackStarted.setDescription('[CAUSE] The sapEthLoopbackStarted notification is generated when the\n         SAP is placed into loopback.\n\n         [EFFECT] This notification is informational only.')
sapEthLoopbackStopped = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 4, 3, 0, 55)).setObjects(("TIMETRA-SAP-MIB", "sapEthLoopbackMode"))
if mibBuilder.loadTexts: sapEthLoopbackStopped.setStatus('current')
if mibBuilder.loadTexts: sapEthLoopbackStopped.setDescription('[CAUSE] The sapEthLoopbackStopped notification is generated when the\n         SAP is removed from loopback.\n\n         [EFFECT] This notification is informational only.')
sapTunnelEncapIpMtuTooSmall = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 4, 3, 0, 56)).setObjects(("TIMETRA-SERV-MIB", "svcId"), ("TIMETRA-SAP-MIB", "sapPortId"), ("TIMETRA-SAP-MIB", "sapEncapValue"), ("TIMETRA-SAP-MIB", "sapTunnelNotifyName"), ("TIMETRA-SAP-MIB", "sapTunnelNotifyConfigIpMtu"), ("TIMETRA-SAP-MIB", "sapTunnelNotifyEncapOverhead"), ("TIMETRA-SAP-MIB", "sapTunnelNotifyConfigEncapIpMtu"))
if mibBuilder.loadTexts: sapTunnelEncapIpMtuTooSmall.setStatus('current')
if mibBuilder.loadTexts: sapTunnelEncapIpMtuTooSmall.setDescription("[CAUSE] The sapTunnelEncapIpMtuTooSmall notification is generated when\n         the addition of tunnel encapsulation to a packet at or near the IP\n         Tunnel's configured IP MTU may cause it to exceed the tunnel's\n         configured encapsulated IP MTU.\n\n         [EFFECT] The pre-encapsulated packet may be fragmented, and will\n         require reassembly by the tunnel remote endpoint, causing a\n         performance impact.\n\n         [RECOVERY] Configured IP MTU and/or encapsulated IP MTU may need to be\n         changed depending on the size of the encapsulation overhead as\n         indicated in 'sapTunnelNotifyEncapOverhead', and the transmission\n         capabilities of the tunnel's transport network.")
sapHostRipListenerSetupFailed = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 4, 3, 0, 57)).setObjects(("TIMETRA-SERV-MIB", "custId"), ("TIMETRA-SERV-MIB", "svcId"), ("TIMETRA-SERV-MIB", "svcVpnId"), ("TIMETRA-SAP-MIB", "sapPortId"), ("TIMETRA-SAP-MIB", "sapEncapValue"), ("TIMETRA-SAP-MIB", "sapRipListenerHostIpAddr"), ("TIMETRA-SAP-MIB", "sapRipListenerHostIpAddrType"), ("TIMETRA-SAP-MIB", "sapRipListenerVRtrID"), ("TIMETRA-SAP-MIB", "sapRipListenerNotifDescription"))
if mibBuilder.loadTexts: sapHostRipListenerSetupFailed.setStatus('current')
if mibBuilder.loadTexts: sapHostRipListenerSetupFailed.setDescription('The sapHostRipListenerSetupFailed notification is generated when the\n         system was unable to set up a RIP listener for the given host.\n\n         [CAUSE] <To be documented>\n\n         [EFFECT] <To be documented>\n\n         [RECOVERY] No recovery is required on this system.')
sapStatHost6DynMacConflict = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 4, 3, 0, 58)).setObjects(("TIMETRA-SAP-MIB", "sapStatHost6DynMacAddress"), ("TIMETRA-SAP-MIB", "sapNotifyReason"))
if mibBuilder.loadTexts: sapStatHost6DynMacConflict.setStatus('current')
if mibBuilder.loadTexts: sapStatHost6DynMacConflict.setDescription('The sapStatHost6DynMacConflict notification is generated when the\n         system was unable to update the MAC address of a static IPv6 host.\n\n         [CAUSE] The system failed to update the MAC address of a static IPv6\n         host.\n\n         [EFFECT] The static IPv6 host has a MAC address that is not up to\n         date.\n\n         [RECOVERY] The recovery action depends on the exact reason why the\n          MAC update failed. This is clarified in the sapNotifyReason object.')
tmnxIpTunnelOperStateChange = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 4, 3, 0, 59)).setObjects(("TIMETRA-SAP-MIB", "tmnxIpTunnelAdminState"), ("TIMETRA-SAP-MIB", "tmnxIpTunnelOperState"), ("TIMETRA-SAP-MIB", "tmnxIpTunnelOperFlags"))
if mibBuilder.loadTexts: tmnxIpTunnelOperStateChange.setStatus('current')
if mibBuilder.loadTexts: tmnxIpTunnelOperStateChange.setDescription('[CAUSE] The tmnxIpTunnelOperStateChange notification is generated when\n         there is a change in tmnxIpTunnelOperState for an IP tunnel.\n\n         [EFFECT] When the tunnel is operationally down, traffic arriving at\n         the tunnel endpoints will not be encapsulated and transported.')
svcEvpnMplsMacMoveExceedNonBlock = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 4, 3, 0, 60)).setObjects(("TIMETRA-SERV-MIB", "tlsFdbEvpnMplsTEPAddrType"), ("TIMETRA-SERV-MIB", "tlsFdbEvpnMplsTEPAddr"), ("TIMETRA-SERV-MIB", "tlsFdbEvpnMplsLabel"), ("TIMETRA-SERV-MIB", "tlsFdbEvpnMplsEthSegId"), ("TIMETRA-SERV-MIB", "tlsFdbBackboneDstMac"), ("TIMETRA-SERV-MIB", "svcId"), ("TIMETRA-SERV-MIB", "custId"), ("TIMETRA-SERV-MIB", "svcTlsMacMoveMaxRate"), ("TIMETRA-SAP-MIB", "sapTlsNotifyMacAddr"))
