sapReceiveOwnBpdu = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 4, 5, 0, 13)).setObjects(("TIMETRA-SERV-MIB", "custId"), ("TIMETRA-SERV-MIB", "svcId"), ("TIMETRA-SAP-MIB", "sapPortId"), ("TIMETRA-SAP-MIB", "sapEncapValue"), ("TIMETRA-SERV-MIB", "tmnxOtherBridgeId"))
